function immediateRisk(n,id){if(!E.atId(n,id))return true;let opp=n.turn;if(E.threats(n,opp,null,id).length)return true;for(const m of E.moves(n,opp)){if(m.capture)continue;let p=E.atId(n,m.id);const test={...n,pieces:n.pieces.map(a=>a.id===p.id?{...a,x:m.x,y:m.y}:a)};if(E.threats(test,opp,p.id,id).length)return true;}return false;}
